    display: flex;
    gap: 30px;
    margin-bottom: 15px;
  }
  .left-column {
    flex: 0 0 42%;
    display: flex;
    flex-direction: column;
    gap: 10px;
  }
  .right-column {
    flex: 0 0 54%;
  }

  /* Ad Boxes */
  .ad-box {
    border: 1px solid #000;
    padding: 20px;
    text-align: center;
    box-sizing: border-box;
  }

  /* Box 1 */
  .box-1 {
    font-family: Arial, sans-serif;
    padding: 40px 20px;
  }
  .box-1 .title {
    font-size: 1.1rem;
    margin-bottom: 5px;
    letter-spacing: 1px;
  }
  .box-1 .subtitle {
    font-size: 1.1rem;
    margin-bottom: 40px;
    letter-spacing: 1px;
  }
  .box-1 .brand {
    font-size: 1rem;
    margin-bottom: 20px;
    letter-spacing: 1px;
  }
  .box-1 .address {
    font-size: 0.75rem;
    margin-top: 40px;
    margin-bottom: 15px;
  }
  .box-1 .invite {
    font-size: 0.8rem;
  }

  /* Box 2 */
  .box-2 {
    border-top: 3px double #000;
    border-bottom: 3px double #000;
    font-family: Arial, sans-serif;
    padding: 25px 20px;
  }
  .box-2 .script-title {
    font-family: "Brush Script MT", "Lucida Handwriting", cursive;
    font-size: 1.8rem;
    line-height: 1.2;
    margin-bottom: 15px;
  }
  .box-2 .address-row {
    display: flex;
    justify-content: space-between;
    font-size: 0.85rem;
    margin-bottom: 15px;
  }
  .box-2 .presents {
    font-size: 0.9rem;
    letter-spacing: 1px;
    margin-bottom: 15px;
  }
  .box-2 .desc {
    font-size: 0.75rem;
    text-align: justify;
    line-height: 1.4;
    margin-bottom: 15px;
  }
  .box-2 .booth {
    font-size: 0.9rem;
  }

  /* Box 3 */
  .box-3 {
    border-top: 3px double #000;
    font-family: "Times New Roman", Times, serif;
    padding: 25px 20px;
  }
  .box-3 .title {
    font-size: 1.8rem;
    font-weight: bold;
    margin-bottom: 5px;
  }
  .box-3 .line-break {
    width: 25%;
    border-top: 2px solid #000;
    margin: 10px 0 15px 0;
  }
  .box-3 .featuring {
    font-size: 1.2rem;
    font-style: italic;
    font-weight: bold;
    margin-bottom: 15px;
  }
  .box-3 .brick {
    font-size: 1.2rem;
    font-weight: bold;
    margin-bottom: 15px;
  }
  .box-3 .and {
    font-size: 1.2rem;
    font-style: italic;
    font-weight: bold;
    margin-bottom: 15px;
  }
  .box-3 .tile {
    font-size: 1.2rem;
    font-weight: bold;
    letter-spacing: 4px;
    margin-bottom: 25px;
  }
  .box-3 .address-row {
    display: flex;
    justify-content: space-between;
    font-size: 1rem;
    font-weight: bold;
  }

  /* Article */
  .article-title {
    text-align: center;
    font-family: Arial, sans-serif;
    font-size: 1.4rem;
    letter-spacing: 2px;
    margin-bottom: 30px;
    margin-top: 10px;
  }
  .article-title div {
    margin-bottom: 15px;
  }
  .article-text p {
    text-align: justify;
    text-indent: 2em;
    line-height: 1.3;
    font-size: 0.95rem;
    margin-top: 0;
    margin-bottom: 12px;
  }

  /* Bottom Ad */
  .bottom-ad {
    border: 1px solid #000;
    border-top: 3px double #000;
    padding: 20px;
    text-align: center;
    font-family: Arial, sans-serif;
    margin-bottom: 10px;
  }
  .bottom-ad .complete {
    font-size: 1.2rem;
    font-weight: bold;
    letter-spacing: 1px;
  }
  .bottom-ad .rendering {
    font-size: 6.5rem;
    font-weight: 900;
    font-family: "Arial Black", "Impact", sans-serif;
    letter-spacing: -3px;
    line-height: 1;
    margin: 10px 0;
    transform: scaleY(1.15);
    display: inline-block;
  }
  .bottom-ad .service {
    font-size: 1.1rem;
    font-weight: bold;
    letter-spacing: 1px;
    margin-bottom: 15px;
  }
  .bottom-ad .desc {
    font-size: 0.85rem;
    text-align: justify;
    text-indent: 3em;
    line-height: 1.4;
    margin-bottom: 15px;
    padding: 0 60px;
  }
  .bottom-ad .booth {
    font-size: 0.85rem;
    margin-bottom: 20px;
  }
  .bottom-ad .footer-cols {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    font-size: 0.75rem;
    padding: 0 20px;
  }
  .bottom-ad .footer-cols > div {
    text-align: center;
  }
  .bottom-ad .italic {
    font-style: italic;
  }

  /* Page Footer */
  .page-footer {
    display: flex;
    justify-content: space-between;
    font-family: Arial, sans-serif;
    font-size: 0.9rem;
    padding-top: 5px;
  }
</style>
